import {dateKey,addDays,daysBetween,dayNumber,wordCount,overall,rawGuide,secondsLeft,clock,emptyState,validateState,nextReview,freshMocks,recommendation} from './core.mjs?v=20261015-4';
import {nav,prompts,checks,cues,part1,part3,days,sources} from './content.mjs?v=20261015-4';
import {lessons} from './lessons.mjs?v=20261015-4';
import {ensureLearning,lessonRecord,markDrill,finishLesson,safeLearning,writingReview} from './coach.mjs?v=20261015-4';
import {createLearningUI} from './learning-ui.mjs?v=20261015-4';
import {renderDrill} from './drill-view.mjs?v=20261015-4';
import {writingModels} from './writing-models.mjs?v=20261015-4';
function validateAppState(value){validateState(value);if(!safeLearning(value.learning))throw Error('Invalid guided-learning backup.');return value;}
const KEY='band-seven-lab-v1';
let state,storageAvailable=true;
try{state=localStorage.getItem(KEY)?validateAppState(JSON.parse(localStorage.getItem(KEY))):emptyState();}catch{state=emptyState();storageAvailable=false;}
let learningUI,courseFilter='All',writingReport=null,drillPlays=0;
let videos=[],drills=[],route='',selectedDay=dayNumber(state.settings.start),videoFilter='All',videoSearch='',activeDrill=null,drillAnswers={},drillResult=null,drillStarted=0,questionIndex=0,questionPart=1,reviewRevealed=new Set(),recording=null,audioUrl=null,audioBlob=null,audioCue=null;
const $=s=>document.querySelector(s);
const $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
const fmtDate=s=>new Date((s||dateKey()).slice(0,10)+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'});
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageAvailable=true;$('#save-status').textContent='Saved on this browser';}catch{storageAvailable=false;$('#save-status').textContent='Storage unavailable — export a backup';}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function link(url,label,cls=''){return `<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} <span aria-hidden="true">↗</span></a>`;}
function button(action,label,cls='',data=''){return `<button type="button" class="button ${cls}" data-action="${action}" ${data}>${label}</button>`;}
function head(kicker,title,description){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div><span class="pill">Academic · target 7 overall</span></div>`;}
function empty(title,text,href,label){return `<div class="empty"><strong>${title}</strong>${text}${href?`<br><a class="button small" href="#${href}">${label}</a>`:''}</div>`;}
function prompt(){return prompts.find(p=>p.id===state.selectedPrompt)||prompts[0];}
function draft(){const p=prompt();if(!state.drafts[p.id])state.drafts[p.id]={text:'',checks:checks[p.type].map(()=>false)};return state.drafts[p.id];}
function readTimer(){const t=state.timer;return t?`${t.label} · ${clock(secondsLeft(t))}`:'';}
function timerControls(kind,seconds,label){const mine=state.timer?.kind===kind;return `<div class="timer-box"><div><div class="prompt-meta">${esc(label)}</div><div class="timer-display" data-timer-value="${kind}">${mine?clock(secondsLeft(state.timer)):clock(seconds)}</div></div><div class="button-row">${button('timer-start',mine&&state.timer.running?'Pause':'Start','',`data-kind="${kind}" data-seconds="${seconds}" data-label="${esc(label)}"`)}${button('timer-reset','Reset','subtle',`data-kind="${kind}" data-seconds="${seconds}" data-label="${esc(label)}"`)}</div></div>`;}
function chartHtml(attempts){const list=attempts.filter(a=>a.listening!==null||a.reading!==null).slice(-6);if(!list.length)return empty('Your baseline goes here','Record a fresh full test to start a useful comparison.','scores','Add a result');return `<div class="legend"><span><i></i>Listening /40</span><span><i class="reading"></i>Academic Reading /40</span></div><div class="chart" role="img" aria-label="Fresh practice results: ${esc(list.map(a=>`${a.source}: listening ${a.listening??'unrecorded'}, reading ${a.reading??'unrecorded'}`).join('; '))}">${list.map(a=>`<div class="chart-group">${a.listening!==null?`<div class="chart-bar" style="height:${a.listening/40*100}%"><span>${a.listening}</span></div>`:''}${a.reading!==null?`<div class="chart-bar reading" style="height:${a.reading/40*100}%"><span>${a.reading}</span></div>`:''}</div>`).join('')}</div><div class="chart-labels">${list.map(a=>`<span>${fmtDate(a.date)}</span>`).join('')}</div>`;}
function legacyToday(){const rec=recommendation(state),done=Object.values(state.tasks).filter(Boolean).length,total=days.reduce((n,d)=>n+d.tasks.length,0),fresh=freshMocks(state),due=state.mistakes.filter(m=>m.due<=dateKey()).length,examDays=daysBetween(dateKey(),state.settings.exam),d=days[selectedDay-1];return head('YOUR SEVEN-DAY SPRINT',`Make today count.`,`Your goal is Band 7 overall. Build a baseline, practise deliberately, and use fresh evidence to see what changes.`)+`<section class="hero"><div><div class="eyebrow">YOUR NEXT BEST STEP</div><h2>${esc(rec.title)}</h2><p>${esc(rec.text)}</p><a class="button lime" href="#${rec.route}">${rec.action} <span>↗</span></a></div><div class="hero-orbit"><strong>${examDays>=0?examDays:'✓'}</strong><small>${examDays>=0?'days to your test':'test date passed'}</small></div></section><div class="metrics"><div class="metric"><div class="metric-label">Your study day <span>↗</span></div><div class="metric-value">${dayNumber(state.settings.start)}<span class="muted" style="font-size:16px"> / 7</span></div><div class="metric-caption">Adjust dates in Settings</div></div><div class="metric"><div class="metric-label">Fresh mocks</div><div class="metric-value">${fresh.length}</div><div class="metric-caption">Repeated tests stay separate</div></div><div class="metric"><div class="metric-label">Plan completed</div><div class="metric-value">${Math.round(done/total*100)}<span style="font-size:18px">%</span></div><div class="metric-caption">${done} of ${total} study blocks</div></div><div class="metric"><div class="metric-label">Mistakes due</div><div class="metric-value">${due}</div><div class="metric-caption">Recall first, then reveal</div></div></div><div class="grid-2"><section class="card"><div class="card-head"><h2>Your week, one day at a time</h2><span class="tag">${state.settings.hours} h/day</span></div><div class="day-tabs" role="group" aria-label="Select study day">${days.map((x,i)=>`<button class="day-tab ${i===selectedDay-1?'active':''}" data-action="day" data-day="${i+1}" aria-pressed="${i===selectedDay-1}">DAY<strong>${i+1}</strong></button>`).join('')}</div><div class="eyebrow">${d.focus}</div><h3 style="margin-top:7px">${d.name}</h3>${d.tasks.map((t,i)=>{const id=`day-${selectedDay}-${i}`;return `<div class="task ${state.tasks[id]?'done':''}"><label><input type="checkbox" data-task="${id}" ${state.tasks[id]?'checked':''}><span>${t[0]}</span></label><span class="task-time">${t[2]} min*</span><a href="#${t[1]}" aria-label="Open ${esc(t[0])}">↗</a></div>`;}).join('')}<div class="progress-track"><div class="progress-fill" style="width:${d.tasks.filter((t,i)=>state.tasks[`day-${selectedDay}-${i}`]).length/d.tasks.length*100}%"></div></div><p class="text-small muted" style="margin:16px 0 0">*Suggested focused time; breaks are extra. Scale targeted blocks to your available hours. Full mock timing stays fixed.</p></section><div><section class="card"><div class="card-head"><h2>Fresh-test evidence</h2><a class="text-small" href="#scores">View results ↗</a></div>${chartHtml(fresh)}<p class="text-small muted" style="margin:17px 0 0">These are raw marks, not a predicted overall band. Different tests can vary in difficulty.</p></section><section class="card"><div class="eyebrow">THE PRACTICE LOOP</div><h3 style="margin-top:10px">Learn it. Try it. Revisit it.</h3><p class="text-small muted">Watch one relevant lesson, do its exercise, and log what went wrong. A watched video is separate from completed practice.</p><a class="button outline small" href="#videos">Explore your video library ↗</a></section></div></div>`;}
function legacyWriting(){const p=prompt(),d=draft(),n=wordCount(d.text),minimum=getWritingMinimum(p),hist=state.writingHistory.filter(h=>h.promptId===p.id).slice().reverse();return head('PRACTISE → REVIEW → REVISE','Your writing studio.','Write under time pressure, keep your first draft, and revise with the actual assessment criteria in mind.')+`<div class="writing-layout"><section class="card"><label for="prompt-select">Choose an original practice task</label><select id="prompt-select">${prompts.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select><div class="prompt-panel"><div class="prompt-meta">${minimum===60?'GUIDED PARAGRAPH PRACTICE · AIM FOR 60–100 WORDS':`ORIGINAL PRACTICE · TASK ${p.type} · AT LEAST ${minimum} WORDS`}</div><p>${esc(p.text)}</p>${p.table?`<div class="table-wrap"><table><caption>${p.table.caption} · fictional data</caption><thead><tr>${p.table.headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${p.table.rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}</div>${timerControls('writing-'+p.id,minimum===60?720:p.type===1?1200:2400,minimum===60?'Paragraph practice':`Task ${p.type} practice`)}<label for="writing-text">Your answer <span class="muted">· autosaved while you write</span></label><textarea class="writing-editor" id="writing-text" placeholder="Start your answer here…" spellcheck="false">${esc(d.text)}</textarea><div class="editor-stats"><span><strong id="word-count">${n}</strong> words <span id="word-hint">${n<minimum?`· ${minimum-n} below the minimum`:'· minimum reached'}</span></span><span>Length alone does not determine your band.</span></div><div class="button-row">${button('review-writing','Get a revision plan')}${button('save-writing','Save my attempt','outline')}${button('show-model','Study a worked example','subtle')}</div><details class="editor-tools"><summary>Compare revisions or share your answer</summary><div class="button-row">${button('compare-writing','Compare my revisions','subtle small')}${button('copy-feedback','Copy for feedback','outline small')}${button('download-writing','Download answer','subtle small')}</div></details><p class="text-small muted" style="margin-top:16px">Get a revision plan, inspect the worked example, then save a revised snapshot. For an assessed band, share the actual answer with a teacher or this chat.</p></section><div><section class="card"><div class="eyebrow">YOUR SELF-REVIEW</div><h2 style="margin-top:9px">What to inspect in this answer</h2><p class="text-small muted">These prompts help you inspect your work. Ticking them is not an IELTS score.</p>${reviewChecks(p).map((c,i)=>`<label class="check-item"><input type="checkbox" data-writing-check="${i}" ${d.checks[i]?'checked':''}><span>${c}</span></label>`).join('')}<div class="rule"></div>${link(sources[3][1],'Open official Writing descriptors','text-small')}<p class="text-small muted" style="margin-top:14px">Task 1: aim for an accurate overview and useful comparisons.<br>Task 2: answer every part, take a clear position and develop your ideas. Task 2 counts twice.</p></section><section class="card"><div class="card-head"><h2>Draft snapshots</h2><span class="tag">${hist.length}</span></div>${hist.length?hist.slice(0,8).map((h,i)=>`<div class="history-item"><span>${fmtDate(h.date)} · ${wordCount(h.text)} words</span>${button('view-writing','View','subtle small',`data-id="${h.id}"`)}</div>`).join(''):empty('Keep your first attempt','Save it before you revise, then compare the two.')}</section></div></div>`;}
function legacySpeaking(){const index=Math.min(cues.length-1,Math.max(0,state.selectedCue)),c=cues[index],notes=state.speakingNotes[index]||'';return head('SAY IT OUT LOUD','Your speaking room.','Practise the full interview, record a sample, and choose one thing to improve on the next fresh question.')+`<div class="grid-2"><section class="card"><div class="card-head"><h2>Part 2 · The long turn</h2><span class="tag">${index+1} / ${cues.length}</span></div><label for="cue-select">Choose a cue card</label><select id="cue-select">${cues.map((x,i)=>`<option value="${i}" ${i===index?'selected':''}>${i+1}. ${x[0]}</option>`).join('')}</select><div class="cue"><div class="prompt-meta">DESCRIBE…</div><h2 style="margin-top:8px">${esc(c[0])}</h2><p class="text-small">You should say:</p><ul>${c.slice(1).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><span class="text-small muted">One minute to prepare. Speak for one to two minutes.</span></div><div class="button-row">${button('speak-prep','1 min preparation','',`data-index="${index}"`)}${button('speak-talk','2 min speaking','outline',`data-index="${index}"`)}${button('next-cue','Next cue card →','subtle')}</div><div class="timer-box"><div class="timer-display" id="speaking-clock">${state.timer?.kind.startsWith('speaking')?clock(secondsLeft(state.timer)):'01:00'}</div><span class="text-small muted" id="speaking-phase">${state.timer?.kind.startsWith('speaking')?esc(state.timer.label):'Choose preparation or speaking'}</span></div><label for="speaking-notes">Keyword notes and your review</label><textarea id="speaking-notes" rows="4" placeholder="Before: keywords, not a script. After: one thing to improve.">${esc(notes)}</textarea><div class="rule"></div><h3>Record and listen back</h3><p class="text-small muted">Microphone permission is optional. Recordings stay in this session; download each one you want to keep. They are not included in backups.</p><div id="recorder-area">${recorderHtml()}</div><div class="notice">This room does not grade your speech. A transcript alone cannot establish pronunciation or fully measure fluency.</div></section><div><section class="card"><div class="card-head"><h2>Short-answer practice</h2><span class="tag">ORIGINAL QUESTIONS</span></div><div class="tab-row">${button('question-part','Part 1',questionPart===1?'':'subtle',`data-part="1"`)}${button('question-part','Part 3',questionPart===3?'':'subtle',`data-part="3"`)}</div><div class="question-box">${esc((questionPart===1?part1:part3)[questionIndex%(questionPart===1?part1.length:part3.length)])}</div><p class="text-small muted">${questionPart===1?'Answer directly, then add a relevant reason or detail.':'Develop an idea: explain why, add an example or comparison, and qualify it where useful.'}</p>${button('next-question','Next question →','outline small')}<div class="rule"></div><h3>Review your recording</h3><ul class="text-small muted"><li>Did I answer the question and keep going naturally?</li><li>Were the main ideas connected?</li><li>Which repeated error or long hesitation can I improve?</li><li>Could a listener understand me without effort?</li></ul>${link(sources[4][1],'Open Speaking descriptors','text-small')}</section><section class="card"><div class="eyebrow">FULL MOCK FORMAT</div><p class="text-small muted" style="margin-top:12px">Part 1: about 4–5 minutes of familiar questions.<br>Part 2: one minute of preparation, up to two minutes talking, then brief follow-up.<br>Part 3: about 4–5 minutes of discussion.<br>Total: approximately 11–14 minutes.</p><p class="text-small muted">Use a partner to ask follow-ups if possible. Don’t memorise complete answers.</p></section></div></div>`;}
function recorderHtml(){return `<div class="button-row">${recording?button('record-stop','<span class="recording-dot"></span>Stop recording','danger'):button('record-start','● Start recording','outline')}${audioBlob?button('audio-download','Download recording','subtle'):''}</div><div id="mic-status" class="text-small muted" style="margin-top:10px">${recording?'Recording now. Stop when you finish.':audioBlob?`Last recording: ${esc(cues[audioCue]?.[0]||'Speaking practice')}`:''}</div>${audioUrl?`<audio controls src="${esc(audioUrl)}" aria-label="Your speaking practice recording"></audio>`:''}`;}
function drillPage(){return renderDrill({active:activeDrill,drills,state,answers:drillAnswers,result:drillResult,head,button,esc,timerControls,activeLesson:matchingLesson('drill',activeDrill?.id)});}
function scores(){const fresh=freshMocks(state),complete=fresh.filter(a=>a.bands.every(b=>b!==null)),latest=complete.at(-1),value=latest?overall(latest.bands):null,met=latest&&value>=7&&(!state.settings.minimum||latest.bands.every(b=>b>=state.settings.minimum));return head('MEASURE THE RIGHT THINGS','Your mock results.','Log complete tests from official sources. Keep fresh tests, repeats and untimed attempts separate.')+`<div class="grid-even"><section class="card"><div class="card-head"><h2>Record a practice test</h2><span class="tag">FULL TESTS ONLY</span></div><p class="text-small muted">Use the test’s own answer key and band conversion. Raw marks alone do not produce an exact band. Leave unknown scores blank.</p><div class="button-row" style="margin:16px 0">${link(sources[1][1],'Official samples','button outline small')}${link(sources[2][1],'IELTS Ready','button outline small')}</div><form id="mock-form"><div class="form-row"><label for="mock-source">Test source and identifier</label><input id="mock-source" name="source" required maxlength="300" placeholder="e.g. IELTS Ready — Mock 1"></div><div class="field-grid form-row"><div><label for="mock-date">Date completed</label><input id="mock-date" type="date" name="date" value="${dateKey()}" required></div><div><label for="mock-mode">Attempt type</label><select id="mock-mode" name="mode"><option value="fresh">Fresh · first time seeing it</option><option value="repeat">Repeated test</option><option value="untimed">Untimed / paused / with help</option></select></div></div><div class="field-grid form-row"><div><label for="mock-l">Listening /40</label><input id="mock-l" type="number" name="listening" min="0" max="40" step="1" placeholder="Optional"></div><div><label for="mock-r">Academic Reading /40</label><input id="mock-r" type="number" name="reading" min="0" max="40" step="1" placeholder="Optional"></div></div><h3 style="margin-top:22px">Section bands, when available</h3><p class="text-small muted">L/R: enter the source’s reported bands. W/S: use external assessment or a clearly labelled estimate.</p><div class="field-grid four form-row">${['Listening','Reading','Writing','Speaking'].map((s,i)=>`<div><label for="band-${i}">${s}</label><input id="band-${i}" name="band${i}" type="number" min="0" max="9" step="0.5" placeholder="—"></div>`).join('')}</div><div class="form-row"><label for="mock-provenance">Where did the Writing/Speaking bands come from?</label><select id="mock-provenance" name="provenance"><option value="unknown">Not assessed / unknown</option><option value="teacher">Teacher assessment (practice)</option><option value="ai">AI estimate (provisional)</option><option value="self">My own estimate (provisional)</option><option value="official">Official IELTS test result</option></select></div><button class="button">Save test result</button><div id="mock-error" class="form-error" role="alert"></div></form></section><div><section class="card"><div class="card-head"><h2>Latest complete fresh profile</h2><span class="tag">${latest?esc(latest.provenance):'NO PROFILE YET'}</span></div>${latest?`<div class="score-big">${value.toFixed(1)}<small> overall</small></div><div class="profile">${latest.bands.map((b,i)=>`<div><small>${['LISTENING','READING','WRITING','SPEAKING'][i]}</small><strong>${b.toFixed(1)}</strong></div>`).join('')}</div><p class="text-small muted">${esc(latest.source)} · ${fmtDate(latest.date)} · W/S: ${esc(latest.provenance)}.<br>${met?'This recorded profile meets your configured target. Check it again with a fresh test.':'This recorded profile does not yet meet your configured target.'}</p><div class="notice">${latest.provenance==='official'?'A reported official result.':'Practice evidence, not an official result or a guarantee. Self/AI/teacher estimates introduce uncertainty.'} Overall is calculated only from four bands recorded in this same attempt.</div>`:empty('Not enough evidence yet','Record all four section bands in one fresh attempt to see a complete profile. No missing skill is assumed.')}</section><section class="card"><div class="card-head"><h2>Fresh raw-score trend</h2></div>${chartHtml(fresh)}<div class="notice">Published Band 7 benchmark: roughly 30/40 in Listening and Academic Reading. Around 35/40 is the Band 8 benchmark. Exact cutoffs vary. Aim beyond the minimum.</div>${link(sources[0][1],'How IELTS scoring works','text-small')}</section></div></div><section class="card" style="margin-top:22px"><div class="card-head"><h2>Every attempt, honestly labelled</h2><span class="tag">${state.mockAttempts.length} RECORDS</span></div>${state.mockAttempts.length?`<div class="scroll-table"><table><thead><tr><th>Test</th><th>Type</th><th>L /40</th><th>R /40</th><th>Band profile L/R/W/S</th><th></th></tr></thead><tbody>${state.mockAttempts.slice().reverse().map(a=>`<tr><td>${esc(a.source)}<br><small class="muted">${fmtDate(a.date)}</small></td><td><span class="tag ${a.mode==='fresh'?'':'orange'}">${a.mode}</span></td><td title="${esc(rawGuide(a.listening,'Listening'))}">${a.listening??'—'}</td><td title="${esc(rawGuide(a.reading,'Reading'))}">${a.reading??'—'}</td><td>${a.bands.map(b=>b??'—').join(' / ')}<br><small class="muted">W/S: ${esc(a.provenance)}</small></td><td>${button('delete-mock','Delete','subtle small',`data-id="${a.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Your honest starting point','One fresh baseline is more useful than a guessed score.')}</section>`;}
function mistakes(){const sorted=state.mistakes.slice().sort((a,b)=>a.due.localeCompare(b.due));return head('MAKE ERRORS USEFUL','Your mistake notebook.','Recall the answer before revealing it. Review again tomorrow, then space successful recalls further apart.')+`<div class="grid-2"><section><div class="card"><h2>Add something worth remembering</h2><form id="mistake-form"><div class="field-grid form-row"><div><label for="mistake-skill">Skill</label><select id="mistake-skill" name="skill">${['Listening','Reading','Writing','Speaking','Language'].map(x=>`<option>${x}</option>`).join('')}</select></div><div><label for="mistake-tag">Error type</label><input id="mistake-tag" name="tag" maxlength="100" placeholder="e.g. distractor / overview / articles" required></div></div><div class="form-row"><label for="mistake-problem">Question or mistake to recall</label><textarea id="mistake-problem" name="problem" rows="2" maxlength="2000" required></textarea></div><div class="form-row"><label for="mistake-fix">Correction, evidence and rule</label><textarea id="mistake-fix" name="fix" rows="3" maxlength="5000" required></textarea></div><button class="button">Add to tomorrow’s review</button></form></div>${sorted.length?sorted.map(m=>`<article class="mistake-card"><div><span class="tag">${esc(m.skill)}</span><span class="tag">${esc(m.tag)}</span><span class="tag ${m.due<=dateKey()?'orange':''}">${m.due<=dateKey()?'DUE NOW':'REVIEW '+fmtDate(m.due)}</span></div><h3>${esc(m.problem)}</h3>${reviewRevealed.has(m.id)?`<div class="mistake-answer">${esc(m.fix)}</div><p class="text-small muted">Could you explain the correction before seeing it?</p><div class="button-row">${button('review-good','Recalled correctly','',`data-id="${m.id}"`)}${button('review-again','Needs another try','outline',`data-id="${m.id}"`)}${button('delete-mistake','Delete','subtle small',`data-id="${m.id}"`)}</div>`:button('reveal-mistake','Reveal correction','outline small',`data-id="${m.id}"`)}</article>`).join(''):empty('Your errors can teach you','Missed drill questions arrive here automatically. Add errors from official tests and your own writing, too.')}</section><aside><div class="card"><div class="eyebrow">WHY THIS LOOP EXISTS</div><h2 style="margin-top:10px">Retrieve, then check.</h2><p class="text-small muted">Try to explain the answer from memory. Then reveal the correction and compare. Feedback helps prevent a wrong answer from becoming a habit.</p><p class="text-small muted">A successful recall schedules a later review. A miss comes back tomorrow. The intervals are a practical study schedule, not an IELTS score prediction.</p><div class="rule"></div><h3>Measure transfer too</h3><p class="text-small muted">Remembering an old answer is useful. Improving on an unseen official test is stronger evidence that your skill is changing.</p></div></aside></div>`;}
function videosPage(){const list=videos.filter(v=>(videoFilter==='All'||v.skill===videoFilter)&&`${v.title} ${v.topic} ${v.channel}`.toLowerCase().includes(videoSearch.toLowerCase())),practised=videos.filter(v=>state.videos[v.id]?.practised).length;return head('WATCH ONE. DO SOMETHING WITH IT.','Your video library.',`${videos.length} researched YouTube lessons, grouped by skill. Each one has a practice action so the learning continues after the video.`)+`<div class="notice">Start with the crash course and your weakest skill. The longer courses are reference libraries—use relevant chapters, rather than spending the week watching everything. Titles mentioning bands are the creators’ titles, not promises.</div><div class="field-grid"><div class="filter-row" role="group" aria-label="Filter videos by skill">${['All','Orientation','Listening','Reading','Writing','Speaking'].map(f=>`<button class="filter ${f===videoFilter?'active':''}" data-action="video-filter" data-filter="${f}" aria-pressed="${f===videoFilter}">${f}</button>`).join('')}</div><div style="align-self:center"><label class="sr-only" for="video-search">Search videos</label><input id="video-search" type="search" placeholder="Search topics or creators…" value="${esc(videoSearch)}"></div></div><p class="text-small muted">${list.length} lessons shown · ${practised} follow-up exercises marked complete · researched 14 October 2026</p><div class="video-grid">${list.map(v=>{const prog=state.videos[v.id]||{watched:false,practised:false};return `<article class="video-card"><div class="video-top"><span class="skill-label">${esc(v.skill)}<br><small>PREP LESSON</small></span>${link(v.url,'▶','play')}</div><div class="video-body"><div><span class="tag">${esc(v.priority)}</span><span class="tag">${esc(v.topic)}</span></div><h3>${esc(v.title)}</h3><div class="channel">${esc(v.channel)} · YouTube</div><div class="video-exercise"><strong>After watching</strong><br>${esc(v.exercise)}</div><label class="check-item"><input type="checkbox" data-video="${v.id}" data-status="watched" ${prog.watched?'checked':''}><span>I watched the relevant lesson</span></label><label class="check-item"><input type="checkbox" data-video="${v.id}" data-status="practised" ${prog.practised?'checked':''}><span>I completed the follow-up exercise</span></label>${link(v.url,'Watch on YouTube','button outline small')}</div></article>`;}).join('')}</div>${!list.length?empty('No matching lessons','Try a different topic or clear the search.'):''}`;}
function settings(){return head('YOUR PLAN. YOUR DATA.','Make it work for you.','Set your dates, keep a backup, and see the sources behind the study tools.')+`<div class="grid-even"><div><section class="card"><h2>Your study settings</h2><form id="settings-form"><div class="field-grid form-row"><div><label for="settings-start">Preparation starts</label><input id="settings-start" name="start" type="date" value="${state.settings.start}" required></div><div><label for="settings-exam">Test date</label><input id="settings-exam" name="exam" type="date" value="${state.settings.exam}" required></div></div><div class="field-grid form-row"><div><label for="settings-hours">Focused study hours/day</label><input id="settings-hours" name="hours" type="number" value="${state.settings.hours}" min="1" max="8" step="0.5" required></div><div><label for="settings-min">Minimum in each section, if required</label><select id="settings-min" name="minimum"><option value="">No section minimum entered</option>${[5,5.5,6,6.5,7,7.5,8].map(x=>`<option value="${x}" ${state.settings.minimum===x?'selected':''}>${x.toFixed(1)}</option>`).join('')}</select></div></div><button class="button">Save settings</button><div id="settings-error" class="form-error" role="alert"></div></form><p class="text-small muted">Target: Academic IELTS 7 overall. Check your actual offer for section minimums. Keep a normal sleep schedule; more exhausted hours do not make better evidence.</p></section><section class="card"><h2>Your work stays with you</h2><p class="text-small muted">Drafts, notes, scores and progress are saved in this browser on this device. They do not automatically sync between devices. Clearing browser data can erase them.</p><p class="text-small muted">Export a backup regularly. Speaking audio stays in the current session only—download recordings separately.</p><div class="button-row">${button('export-data','Export backup')}${button('choose-import','Import backup','outline')}${button('download-summary','Download progress report','subtle')}</div><div class="button-row" style="margin-top:10px">${button('backup-text','Copy/paste backup','outline small')}</div><input id="import-file" type="file" accept="application/json,.json" hidden><div class="rule"></div>${button('reset-data','Reset all saved work','outline small')}<div class="notice ${storageAvailable?'':'warning'}">${storageAvailable?'Browser storage is available. A backup gives you a portable copy.':'Storage is currently unavailable or a saved record could not be loaded. Export this session before leaving. Existing stored data has not been intentionally deleted.'}</div></section></div><section class="card"><div class="eyebrow">RESEARCH & LIMITS</div><h2 style="margin-top:10px">What the app measures</h2><p class="research-note">Full-test raw scores come from the answer keys you use. Overall band arithmetic uses only four section bands from a single recorded attempt. Writing checklists, word counts and timer use do not establish a band.</p><p class="research-note">The original mini drills measure item accuracy. Repeats are labelled. The mistake notebook uses recall, corrective feedback and spaced revisits. These are research-informed study tools; this particular app has not been validated as an IELTS intervention.</p><p class="research-note">There is no built-in AI examiner. Bring an exported answer to this chat or a teacher for provisional feedback. Audio assessment needs actual audio. Personal reflections and estimated bands should stay labelled.</p><div class="rule"></div><div class="sources-list">${sources.map(s=>`${link(s[1],s[0])}<p>${esc(s[2])}</p>`).join('')}</div><p class="text-small muted">Sources and video links researched 14 October 2026. Free resources can have optional paid products; sign-up may be required.</p></section></div>`;}
const mainNav=[['today','01','Your next session'],['learn','02','Learn & practise'],['progress','03','Your progress'],['more','04','All tools']];
function render(){ensureLearning(state);const raw=location.hash.slice(1)||'today';route=raw.startsWith('lesson-')?'lesson':raw;if(route==='lesson'&&lessons.some(l=>l.id===raw.slice(7)))ensureLearning(state).current=raw.slice(7);if(![...nav.map(n=>n[0]),'learn','progress','more','lesson'].includes(route))route='today';const group=['today','learn','progress','more'].includes(route)?route:route==='lesson'||['writing','speaking','drills'].includes(route)?'learn':route==='scores'?'progress':'more';$('#navigation').innerHTML=mainNav.map(n=>`<a href="#${n[0]}" class="nav-item ${n[0]===group?'active':''}" ${n[0]===group?'aria-current="page"':''}><span class="nav-num">${n[1]}</span>${n[2]}</a>`).join('');try{const view=route==='lesson'?learningUI.lesson(raw.slice(7)):({today:learningUI.today,learn:learningUI.learn,progress:learningUI.progress,more:learningUI.more,writing,speaking,drills:drillPage,scores,mistakes,videos:videosPage,settings}[route])();const banner=(route==='writing'&&matchingLesson('writing',prompt().id))||(route==='speaking'&&matchingLesson('speaking',String(state.selectedCue)))||(route==='drills'&&matchingLesson('drill',activeDrill?.id));$('#main').innerHTML=(banner?learningUI.banner():'')+view;}catch(e){$('#main').innerHTML=empty('This view could not load','Your saved work is still in this browser. Try reloading or open Settings.','settings','Open Settings');console.error(e);}const title=mainNav.find(n=>n[0]===route)?.[2]||nav.find(n=>n[0]===route)?.[2]||'Guided session';document.title=`${title} · Band Seven`;updateTimer();if(!storageAvailable)$('#save-status').textContent='Storage issue — export a backup';}
function matchingLesson(type,id){const l=lessons.find(l=>l.id===ensureLearning(state).practice);return l?.practice.type===type&&String(l.practice.id)===String(id)?l:null;}
function reviewChecks(p){return getWritingMinimum(p)===60?['My paragraph has one clear main claim.','I explained why or how that claim holds.','I added a relevant example or consequence.','Each sentence develops the same idea.','My vocabulary is precise and appropriate.','I checked grammar and punctuation.']:checks[p.type];}
function getWritingMinimum(p){return matchingLesson('writing',p.id)?.id==='writing-paragraph-development'?60:p.type===1?150:250;}
function writing(){const p=prompt(),d=draft();let html=legacyWriting();if(writingReport?.promptId===p.id&&writingReport.text===d.text){const r=writingReport.report;html+=`<section class="card revision-report" id="writing-report"><div class="eyebrow">YOUR REVISION PLAN</div><h2 style="margin-top:10px">Make the next draft more useful.</h2><p class="text-small muted">${r.words} words · ${r.paragraphs} text block${r.paragraphs===1?'':'s'}. These checks identify specific surface patterns and revision questions, not an IELTS grade.</p>${r.findings.map(f=>`<div class="revision-item"><h3>${esc(f.title)}</h3>${f.quote?`<blockquote>${esc(f.quote)}</blockquote>`:''}<p>${esc(f.detail)}</p></div>`).join('')}<h3>Now inspect meaning and organisation</h3><ol>${r.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ol><div class="button-row">${button('show-model','Compare with a worked example','outline')}${button('copy-feedback','Bring my answer to this chat','subtle')}</div></section>`;}return html;}
function speaking(){const l=matchingLesson('speaking',String(state.selectedCue));if(l&&['speaking-part1','speaking-part3'].includes(l.id)){const part=l.id==='speaking-part1'?1:3;questionPart=part;return head(`SPEAKING PART ${part} · GUIDED PRACTICE`,part===1?'Answer naturally. Add useful detail.':'Develop an idea out loud.','Answer the current question, then move on. Record a short round if you want to listen back.')+`<div class="grid-2"><section class="card"><span class="tag">QUESTION ${questionIndex%(part===1?part1.length:part3.length)+1}</span><div class="question-box">${esc((part===1?part1:part3)[questionIndex%(part===1?part1.length:part3.length)])}</div><p>${part===1?'Give a direct answer, followed by a relevant reason or detail.':'State a view, explain why, and develop it with an example or comparison.'}</p>${button('next-question','I answered — next question →','outline')}<div class="rule"></div><div id="recorder-area">${recorderHtml()}</div><label for="speaking-notes" style="margin-top:20px">After 4–6 answers: what will you improve?</label><textarea id="speaking-notes" rows="4" maxlength="10000" placeholder="Be specific: I repeated ‘very’ often; next time I will use a more precise adjective.">${esc(state.speakingNotes[state.selectedCue]||'')}</textarea><div style="margin-top:16px">${button('save-speaking','Save my reflection & finish')}</div></section><section class="card"><h2>Listen for one useful change</h2><ol><li>Did I answer the actual question?</li><li>Did my reason or example develop the answer?</li><li>Where did I repeat words or struggle to continue?</li><li>Which sentence would I say more clearly next time?</li></ol><p class="text-small muted">Saving a reflection records practice. Pronunciation and fluency need assessment of the audio.</p></section></div>`;}return legacySpeaking().replace('<div class="notice">This room does not grade your speech.',`${button('save-speaking','Save my reflection & finish','outline')}<div class="notice">This room does not grade your speech.`);}
function openDrill(id){activeDrill=drills.find(d=>d.id===id);if(!activeDrill)return;drillAnswers={};drillResult=null;drillPlays=0;drillStarted=Date.now();if(location.hash==='#drills')render();else location.hash='drills';window.scrollTo(0,0);}
function startTimer(kind,seconds,label){if(state.timer?.kind===kind){const left=secondsLeft(state.timer);state.timer=state.timer.running?{...state.timer,running:false,remaining:left}:{...state.timer,running:true,end:Date.now()+(left||seconds)*1000,remaining:left||seconds};}else{if(state.timer?.running&&secondsLeft(state.timer)>0&&!confirm('Replace the running timer with this practice timer?'))return;state.timer={kind,label,running:true,end:Date.now()+seconds*1000,remaining:seconds};}save();render();}
function updateTimer(){const t=state.timer,chip=$('#global-timer');chip.hidden=!t;if(!t)return;const left=secondsLeft(t);chip.textContent=readTimer();$$('[data-timer-value]').forEach(el=>{if(el.dataset.timerValue===t.kind)el.textContent=clock(left);});if(t.kind.startsWith('speaking')&&$('#speaking-clock')){$('#speaking-clock').textContent=clock(left);$('#speaking-phase').textContent=t.label;}if(t.running&&left===0){t.running=false;t.remaining=0;save();toast(`${t.label}: time is up. Save your attempt, then review.`);if(route==='writing'||route==='drills')render();}}
function download(filename,content,type='text/plain'){const blob=content instanceof Blob?content:new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.style.display='none';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function feedbackText(){const p=prompt();if(getWritingMinimum(p)===60)return `IELTS Academic paragraph practice. The full essay prompt is context: ${p.text}\n\nMy body paragraph:\n${draft().text}\n\nGive feedback on this paragraph's main claim, explanation, example, coherence and language. Quote actual issues and suggest revisions. This is not a complete essay, so do not assign a full Writing band.`;return `IELTS Academic practice — ${p.title}\nOriginal prompt: ${p.text}\n${p.table?JSON.stringify(p.table,null,2)+'\n':''}\nMy unedited answer (${wordCount(draft().text)} words):\n${draft().text}\n\nPlease assess this against current public IELTS Writing criteria. Give a cautious estimated band range with uncertainty; identify three highest-impact issues with specific examples, explain corrections, and give a short drill. Do not infer a band from word count alone. Let me revise before giving a full rewrite.`;}
async function copyText(s){try{await navigator.clipboard.writeText(s);toast('Copied. Paste it into this chat or share it with your teacher.');}catch{showModal('Copy your answer',`<textarea rows="14" readonly>${esc(s)}</textarea>`);}}
function showModal(title,html){$('#modal-body').innerHTML=`<h2>${esc(title)}</h2>${html}`;$('#modal').showModal();}
function addMistake(m){const exists=state.mistakes.find(x=>x.origin===m.origin&&m.origin);if(exists){Object.assign(exists,{fix:m.fix,level:0,due:addDays(dateKey(),1)});reviewRevealed.delete(exists.id);}else state.mistakes.push({id:uid(),skill:m.skill,tag:m.tag,problem:m.problem,fix:m.fix,origin:m.origin||null,due:addDays(dateKey(),1),level:0});}
async function beginRecording(){if(!navigator.mediaDevices?.getUserMedia||!globalThis.MediaRecorder){toast('Microphone recording is unavailable here. Use your phone recorder and the same cue-card timer.');return;}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const chunks=[];const r=new MediaRecorder(stream);const cue=state.selectedCue;r.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};r.onstop=()=>{stream.getTracks().forEach(t=>t.stop());if(audioUrl)URL.revokeObjectURL(audioUrl);audioBlob=new Blob(chunks,{type:r.mimeType||'audio/webm'});audioUrl=URL.createObjectURL(audioBlob);audioCue=cue;recording=null;if($('#recorder-area'))$('#recorder-area').innerHTML=recorderHtml();};r.start();recording=r;if($('#recorder-area'))$('#recorder-area').innerHTML=recorderHtml();}catch{toast('Microphone access was not granted. You can still practise with the timer or record on your phone.');}}
document.addEventListener('click',async e=>{if(e.target.closest('a[href="#writing"],a[href="#speaking"],a[href="#drills"]')){ensureLearning(state).practice=null;save();}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;switch(a){
case 'open-lesson':{const l=lessons.find(l=>l.id===b.dataset.id);if(!l)break;ensureLearning(state).current=l.id;lessonRecord(state,l.id);save();if(location.hash==='#lesson-'+l.id)render();else location.hash='lesson-'+l.id;break;}
case 'course-filter':courseFilter=b.dataset.filter;render();break;
case 'lesson-step':{const r=lessonRecord(state,b.dataset.id),step=Number(b.dataset.step);if(step===2&&!r.submitted){toast('Try the quick check first.');break;}r.step=step;save();render();window.scrollTo(0,0);break;}
case 'lesson-practice':{const l=lessons.find(l=>l.id===b.dataset.id);if(!l)break;ensureLearning(state).practice=l.id;ensureLearning(state).current=l.id;save();if(l.practice.type==='drill')openDrill(l.practice.id);else if(l.practice.type==='writing'){state.selectedPrompt=l.practice.id;writingReport=null;save();location.hash='writing';}else{state.selectedCue=Number(l.practice.id);questionIndex=0;questionPart=l.id==='speaking-part3'?3:1;save();location.hash='speaking';}break;}
case 'review-writing':{const p=prompt(),text=draft().text;if(wordCount(text)<10){toast('Write a short attempt first, then ask for a revision plan.');break;}const report=writingReview(text,p.type);if(getWritingMinimum(p)===60){report.minimum=60;report.findings=report.findings.filter(f=>!f.title.startsWith('Develop the answer')&&f.title!=='Make the organisation visible');if(report.words<60)report.findings.unshift({title:'Develop this paragraph to about 60–100 words',detail:'Explain the main claim and add a relevant example or consequence.',quote:''});report.questions=['Underline the one main claim.','Which sentence explains why or how it happens?','Which example or consequence makes the explanation concrete?'];}writingReport={promptId:p.id,text,report};render();$('#writing-report')?.scrollIntoView({behavior:'smooth'});break;}
case 'show-model':{const p=prompt(),model=writingModels[p.id]||writingModels[p.type===1?'table-1':'essay-1'];showModal('Worked example: '+model.title,`<p class="text-small muted">Original teaching example, unscored. Study how the answer is built, then revise your own wording.</p>${model.paragraphs.map(([name,text])=>`<div class="model-paragraph"><span class="tag">${esc(name)}</span><p>${esc(text)}</p></div>`).join('')}<h3>What to notice</h3><ul>${model.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul>`);break;}
case 'compare-writing':{const list=state.writingHistory.filter(h=>h.promptId===prompt().id);if(list.length<2){toast('Save a first draft and a revision of this same prompt to compare them.');break;}const first=list[0],last=list.at(-1);showModal('Your first draft and latest revision',`<div class="grid-even"><div><h3>First draft · ${wordCount(first.text)} words</h3><pre>${esc(first.text)}</pre></div><div><h3>Latest revision · ${wordCount(last.text)} words</h3><pre>${esc(last.text)}</pre></div></div><p class="text-small muted">Look for clearer ideas, better support and fewer recurring errors. Word count alone does not show improvement.</p>`);break;}
case 'save-speaking':{const note=state.speakingNotes[state.selectedCue]||'';if(note.trim().length<15){toast('Write one specific observation in your reflection first.');break;}ensureLearning(state).speaking.push({date:new Date().toISOString(),cue:state.selectedCue,note});const finished=finishLesson(state,lessons,'speaking',String(state.selectedCue));save();render();toast(finished?'Speaking reflection saved. Return to your lesson to continue.':'Speaking reflection saved.');break;}
case 'day':selectedDay=Number(b.dataset.day);render();break;
case 'timer-start':startTimer(b.dataset.kind,Number(b.dataset.seconds),b.dataset.label);break;
case 'timer-reset':if(state.timer?.kind===b.dataset.kind){state.timer={...state.timer,running:false,remaining:Number(b.dataset.seconds),end:0};save();render();}break;
case 'save-writing':{const p=prompt(),d=draft();if(!d.text.trim()){toast('Write an answer before saving a snapshot.');break;}state.writingHistory.push({id:uid(),promptId:p.id,text:d.text,checks:[...d.checks],date:new Date().toISOString()});const finished=wordCount(d.text)>=getWritingMinimum(p)&&finishLesson(state,lessons,'writing',p.id);save();render();toast(finished?'Attempt saved. Return to your lesson to continue.':'Snapshot saved. Revise it, then save another version.');break;}
case 'view-writing':{const h=state.writingHistory.find(x=>x.id===b.dataset.id);if(h)showModal('Saved draft',`<p class="text-small muted">${fmtDate(h.date)} · ${wordCount(h.text)} words</p><pre>${esc(h.text)}</pre>`);break;}
case 'copy-feedback':await copyText(feedbackText());break;
case 'download-writing':download(`ielts-${prompt().id}-${dateKey()}.txt`,feedbackText());break;
case 'speak-prep':startTimer('speaking-prep',60,'Part 2 preparation');break;
case 'speak-talk':startTimer('speaking-talk',120,'Part 2 speaking');break;
case 'next-cue':state.selectedCue=(state.selectedCue+1)%cues.length;save();render();break;
case 'question-part':questionPart=Number(b.dataset.part);questionIndex=0;render();break;
case 'next-question':questionIndex++;render();break;
case 'record-start':await beginRecording();break;
case 'record-stop':if(recording?.state==='recording')recording.stop();break;
case 'audio-download':if(audioBlob)download(`ielts-speaking-card-${audioCue+1}-${dateKey()}.${audioBlob.type.includes('mp4')?'m4a':audioBlob.type.includes('ogg')?'ogg':'webm'}`,audioBlob);break;
case 'open-drill':openDrill(b.dataset.id);break;
case 'close-drill':if(!drillResult&&Object.keys(drillAnswers).length&&!confirm('Leave this unfinished drill? Your submitted results will stay saved.'))break;activeDrill=null;drillResult=null;render();break;
case 'delete-mock':if(confirm('Delete this practice result?')){state.mockAttempts=state.mockAttempts.filter(x=>x.id!==b.dataset.id);save();render();}break;
case 'reveal-mistake':reviewRevealed.add(b.dataset.id);render();break;
case 'review-good':case 'review-again':{const m=state.mistakes.find(x=>x.id===b.dataset.id);if(m){Object.assign(m,nextReview(m.level,a==='review-good'));reviewRevealed.delete(m.id);save();render();toast('Next review: '+fmtDate(m.due));}break;}
case 'delete-mistake':if(confirm('Delete this mistake card?')){state.mistakes=state.mistakes.filter(x=>x.id!==b.dataset.id);save();render();}break;
case 'video-filter':videoFilter=b.dataset.filter;render();break;
case 'export-data':download(`band-seven-backup-${dateKey()}.json`,JSON.stringify(state,null,2),'application/json');toast('Backup exported. Keep your audio downloads separately.');break;
case 'backup-text':showModal('A portable copy of your progress',`<p class="text-small muted">If your browser cannot download files, copy this backup text and keep it in a note. To restore it later, paste the saved text below and choose Restore pasted backup. Restoring replaces this browser’s saved work.</p><label for="backup-text">Backup text</label><textarea id="backup-text" rows="10">${esc(JSON.stringify(state,null,2))}</textarea><div class="button-row" style="margin-top:15px">${button('copy-backup-text','Copy backup text')}${button('restore-backup-text','Restore pasted backup','outline')}</div>`);break;
case 'copy-backup-text':await copyText($('#backup-text').value);break;
case 'restore-backup-text':try{const imported=validateAppState(JSON.parse($('#backup-text').value));if(confirm(`Replace saved work with this backup? It contains ${imported.mockAttempts.length} mock results and ${Object.keys(imported.drafts).length} drafts.`)){imported.timer=null;clearTransient();state=imported;selectedDay=dayNumber(state.settings.start);save();$('#modal').close();render();toast('Backup restored.');}}catch(err){toast('Restore failed: '+err.message);}break;
case 'choose-import':$('#import-file').click();break;
case 'download-summary':download(`ielts-progress-${dateKey()}.txt`,progressReport());break;
case 'reset-data':if(confirm('Reset all drafts, scores, notes and progress in this browser? Export a backup first if you want to keep them.')){clearTransient();state=emptyState();selectedDay=1;save();render();toast('Saved work reset.');}break;
}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='writing-text'){draft().text=el.value;writingReport=null;$('#writing-report')?.remove();save();$('#word-count').textContent=wordCount(el.value);const min=getWritingMinimum(prompt()),n=wordCount(el.value);$('#word-hint').textContent=n<min?`· ${min-n} below the minimum`:'· minimum reached';}if(el.closest('#drill-form')&&el.type==='text')drillAnswers[el.name]=el.value;if(el.id==='speaking-notes'){state.speakingNotes[state.selectedCue]=el.value;save();}if(el.id==='video-search'){videoSearch=el.value;const start=el.selectionStart;render();$('#video-search').focus();$('#video-search').setSelectionRange(start,start);}});
document.addEventListener('change',async e=>{const el=e.target;if(el.dataset.task){state.tasks[el.dataset.task]=el.checked;save();render();}if(el.dataset.writingCheck!==undefined){draft().checks[Number(el.dataset.writingCheck)]=el.checked;save();}if(el.id==='prompt-select'){ensureLearning(state).practice=null;state.selectedPrompt=el.value;save();render();}if(el.id==='cue-select'){state.selectedCue=Number(el.value);save();render();}if(el.dataset.video){const id=el.dataset.video;if(!state.videos[id])state.videos[id]={watched:false,practised:false};state.videos[id][el.dataset.status]=el.checked;save();render();}if(el.type==='radio'&&el.closest('#drill-form'))drillAnswers[el.name]=el.value;if(el.id==='import-file'&&el.files[0]){try{const file=el.files[0];if(file.size>10*1024*1024)throw Error('Please choose a backup smaller than 10 MB.');const imported=validateAppState(JSON.parse(await file.text()));if(confirm(`Replace this browser’s work with this backup? It contains ${imported.mockAttempts.length} mock results, ${Object.keys(imported.drafts).length} drafts and ${imported.mistakes.length} mistakes. Export your current work first if needed.`)){imported.timer=null;clearTransient();state=imported;selectedDay=dayNumber(state.settings.start);save();render();toast('Backup imported. Running timers were cleared.');}}catch(err){toast('Import failed: '+err.message);}el.value='';}});
document.addEventListener('submit',e=>{if(!['mock-form','mistake-form','settings-form','drill-form','lesson-check-form'].includes(e.target.id))return;e.preventDefault();const f=e.target,fd=new FormData(f);if(f.id==='lesson-check-form'){const l=lessons.find(l=>l.id===f.dataset.lesson),r=lessonRecord(state,l.id);r.selected=Number(fd.get('lesson-answer'));r.submitted=true;r.correct=l.check.options[r.selected]===l.check.answer;save();render();return;}if(f.id==='mock-form'){try{const number=name=>fd.get(name)===''?null:Number(fd.get(name));const bands=[0,1,2,3].map(i=>number('band'+i)),provenance=fd.get('provenance');if((bands[2]!==null||bands[3]!==null)&&provenance==='unknown')throw Error('Label where your Writing/Speaking band came from, or leave it blank.');const a={id:uid(),source:fd.get('source').trim(),date:fd.get('date'),mode:fd.get('mode'),listening:number('listening'),reading:number('reading'),bands,provenance,created:Date.now()};if(!a.source)throw Error('Enter the test source and identifier.');if(a.listening===null&&a.reading===null&&bands.every(b=>b===null))throw Error('Enter at least one score.');const candidate={...state,mockAttempts:[...state.mockAttempts,a]};validateAppState(candidate);state=candidate;save();render();toast('Result saved with its attempt type.');}catch(err){$('#mock-error').textContent=err.message;}}
if(f.id==='mistake-form'){const problem=fd.get('problem').trim(),fix=fd.get('fix').trim(),tag=fd.get('tag').trim();if(!problem||!fix||!tag){toast('Add a question, correction and error type.');return;}addMistake({skill:fd.get('skill'),tag,problem,fix});save();render();toast('Added to tomorrow’s review.');}
if(f.id==='settings-form'){try{const settings={start:fd.get('start'),exam:fd.get('exam'),hours:Number(fd.get('hours')),minimum:fd.get('minimum')===''?null:Number(fd.get('minimum'))};if(settings.exam<settings.start)throw Error('Your test date must be on or after your preparation start.');validateAppState({...state,settings});state.settings=settings;selectedDay=dayNumber(settings.start);save();render();toast('Study settings saved.');}catch(err){$('#settings-error').textContent=err.message;}}
if(f.id==='drill-form'){const d=activeDrill;if(d.questions.some(q=>fd.get(q.id)===null||String(fd.get(q.id)).trim()==='')){toast('Answer every question before checking.');return;}const answers=d.questions.map(q=>q.type==='text'?String(fd.get(q.id)).trim():q.options[Number(fd.get(q.id))]);const marked=markDrill(d,answers),first=!state.drillAttempts.some(a=>a.drillId===d.id);state.drillAttempts.push({id:uid(),drillId:d.id,date:new Date().toISOString(),correct:marked.correct,total:d.questions.length,answers,first,plays:d.audio?drillPlays:0,elapsed:Math.round((Date.now()-drillStarted)/1000)});d.questions.forEach((q,i)=>{if(!marked.results[i].correct)addMistake({origin:q.id,skill:d.skill,tag:q.tag,problem:q.question,fix:`Correct answer: ${q.answer}\n${q.explanation}\nYour earlier answer: ${answers[i]}`});});drillResult={...marked,answers,first,wrong:marked.correct<d.questions.length};finishLesson(state,lessons,'drill',d.id);if(state.timer?.kind==='drill-'+d.id){state.timer.remaining=secondsLeft(state.timer);state.timer.running=false;}save();render();window.scrollTo(0,0);}});
document.addEventListener('play',e=>{if(e.target.id==='drill-audio')drillPlays++;},true);
function clearTransient(){ensureLearning(state).practice=null;writingReport=null;activeDrill=null;drillAnswers={};drillResult=null;reviewRevealed.clear();if(recording){recording.onstop=null;if(recording.state==='recording')recording.stop();recording.stream.getTracks().forEach(t=>t.stop());recording=null;}if(audioUrl)URL.revokeObjectURL(audioUrl);audioUrl=null;audioBlob=null;audioCue=null;}
function progressReport(){return `IELTS Academic — progress report\nGenerated ${dateKey()}\nTarget: overall 7${state.settings.minimum?`, minimum ${state.settings.minimum} per section`:''}\n\nMOCK RESULTS\n${state.mockAttempts.map(a=>`${a.date} | ${a.source} | ${a.mode} | L ${a.listening??'?'}/40, R ${a.reading??'?'}/40 | bands L/R/W/S ${a.bands.map(b=>b??'?').join('/')} | W/S ${a.provenance}`).join('\n')}\n\nDRILLS (item accuracy only, not IELTS bands)\n${state.drillAttempts.map(a=>`${a.date} | ${a.drillId} | ${a.correct}/${a.total} | ${a.first?'first attempt':'repeat'}`).join('\n')}\n\nMISTAKES TO WORK ON\n${state.mistakes.map(m=>`${m.skill}: ${m.problem}\nCorrection: ${m.fix}\nReview: ${m.due}`).join('\n\n')}\n\nWriting snapshots: ${state.writingHistory.length}\nVideos with follow-up exercise completed: ${Object.values(state.videos).filter(v=>v.practised).length}\n\nPractice feedback and self/AI assessments are provisional, not official results.`;}
window.addEventListener('hashchange',()=>{if(route==='speaking'&&location.hash!=='#speaking'&&recording?.state==='recording')recording.stop();render();window.scrollTo(0,0);});window.addEventListener('pagehide',()=>{if(recording?.state==='recording')recording.stop();});$('#global-timer').addEventListener('click',()=>{if(!state.timer)return;const kind=state.timer.kind;let destination='drills';if(kind.startsWith('writing-')){state.selectedPrompt=kind.slice(8);destination='writing';save();}else if(kind.startsWith('speaking'))destination='speaking';else if(kind.startsWith('drill-')){const id=kind.slice(6);if(activeDrill?.id!==id){activeDrill=drills.find(d=>d.id===id)||null;drillAnswers={};drillResult=null;drillStarted=Date.now();}}if(location.hash==='#'+destination)render();else location.hash=destination;});
learningUI=createLearningUI({getState:()=>state,getDrills:()=>drills,getVideos:()=>videos,getFilter:()=>courseFilter,esc,head,button,link,lessons});
try{const [videoData,base,extra,listening]=await Promise.all(['videos.json','drills.json','reading-extra.json','listening.json'].map(file=>fetch('./'+file+'?v=20261015').then(r=>{if(!r.ok)throw Error('Practice library unavailable');return r.json();})));videos=videoData;drills=[...base,...extra,...listening];render();setInterval(updateTimer,500);}catch(err){$('#main').innerHTML=empty('The practice library could not load','Check your connection and reload this page. Your saved work stays in this browser.');console.error(err);}
